#!/usr/bin/env bash
# devices-tables-drift — the vendored device tables (`devices_tables.py`, one
# copy per importing package) stay byte-identical and keep their generator
# header.
#
# WHY. `opt/sa02m-modbus-mqtt/devices_tables.py` (bridge, bridge_mr02m_map.py)
# and `opt/sa02m-rs485-roster/devices_tables.py` (roster, model_alias.py) are
# two copies of ONE generated file (CYNTRON-git/devices generated/
# devices_tables.py), written together by scripts/14-cyntron-devices.sh. A hand
# edit to one copy, or a refresh that reached only one, makes the bridge and the
# roster disagree about which module a type id is — silently, since each copy
# still imports. The header is what tells the next editor «do not edit, re-run
# the script»; losing it invites exactly the hand edit this row exists to catch.
#
# CHECKS (no pipes into early-exit consumers — values are captured first):
#   1. both copies exist and are non-empty; every other opt/*/devices_tables.py
#      that appears is compared too (a third copy is not outside the check);
#   2. all copies are byte-identical (cmp -s against the bridge copy);
#   3. line 1 starts with
#      `# generated, do not edit — copied from https://github.com/CYNTRON-git/devices.git generated/devices_tables.py`
#      and line 3 is exactly `# Generated by codegen/gen_python.py. Do not edit.`
#      (the writer's own header, then the generator's);
#   4. non-vacuity: a `MR02M_MODULE_TYPES = [` assignment exists — an emptied or
#      truncated copy that is still "identical" to its twin FAILS.
#
# RED, measured 2026-10-14 on scratch copies of the tree: one byte appended to
# the roster copy (check 2), the bridge copy's line 1 commented with `# `
# (checks 2 and 3), line 3 rewritten in both copies (check 3), the roster copy
# deleted (check 1), both copies emptied (check 1), both truncated to the same
# five header lines (check 4), a drifted third copy under opt/ (check 2). The
# comment-out of the bridge copy's `MR02M_MODULE_TYPES = [` line (checks 2 and
# 4) is registered in comment-mutation-proof — the header lines already start
# with `#`, so the proof cannot comment them out (it skips commented lines).
#
# Run: bash .ai-dev/quality/checks/devices-tables-drift.sh
set -u
ROOT="${DEVICES_TABLES_ROOT:-$(cd "$(dirname "${BASH_SOURCE[0]}")/../../.." && pwd)}"
cd "$ROOT" || exit 1

BRIDGE=opt/sa02m-modbus-mqtt/devices_tables.py
ROSTER=opt/sa02m-rs485-roster/devices_tables.py
HEAD1='# generated, do not edit — copied from https://github.com/CYNTRON-git/devices.git generated/devices_tables.py'
HEAD3='# Generated by codegen/gen_python.py. Do not edit.'

fails=0
ok()  { printf 'devices-tables-drift: ok    %s\n' "$1"; }
bad() { printf 'devices-tables-drift: FAIL  %s\n' "$1"; fails=$((fails + 1)); }

copies=("$BRIDGE" "$ROSTER")
for extra in opt/*/devices_tables.py; do
    [ -f "$extra" ] || continue
    case "$extra" in "$BRIDGE"|"$ROSTER") ;; *) copies+=("$extra") ;; esac
done

present=()
for f in "${copies[@]}"; do
    if [ -s "$f" ]; then
        present+=("$f")
    else
        bad "$f is missing or empty"
    fi
done

if [ -s "$BRIDGE" ]; then
    for f in "${present[@]}"; do
        [ "$f" = "$BRIDGE" ] && continue
        if cmp -s "$BRIDGE" "$f"; then
            ok "$f is byte-identical to $BRIDGE"
        else
            bad "$f differs from $BRIDGE — re-run scripts/14-cyntron-devices.sh, never hand-edit a copy"
        fi
    done
fi

for f in "${present[@]}"; do
    l1=""; l3=""
    { IFS= read -r l1; IFS= read -r _; IFS= read -r l3; } < "$f"
    l1=${l1%$'\r'}; l3=${l3%$'\r'}
    case "$l1" in
        "$HEAD1"*) ok "$f line 1 names the source and the writer" ;;
        *) bad "$f line 1 is not the generator header '$HEAD1' (got: '$l1')" ;;
    esac
    if [ "$l3" = "$HEAD3" ]; then
        ok "$f line 3 is the codegen header"
    else
        bad "$f line 3 is not '$HEAD3' (got: '$l3')"
    fi
    n=$(grep -cE '^MR02M_MODULE_TYPES = \[' "$f")
    if [ "${n:-0}" -ge 1 ]; then
        ok "$f carries the MR02M_MODULE_TYPES table"
    else
        bad "$f has no 'MR02M_MODULE_TYPES = [' assignment — truncated or emptied"
    fi
done

echo
if [ "$fails" -eq 0 ]; then
    echo "devices-tables-drift: ALL OK — ${#present[@]} copies identical, headers intact"
    exit 0
fi
echo "devices-tables-drift: $fails FAIL(s)"
exit 1
